import numpy as np

def column_sums(a):
    """Return one total per column: fold the row axis away."""
    return a.sum(axis=0)

import numpy as np

def top_two(a):
    """Per row, [max, second max] as a fixed (R, 2) array."""
    order = np.argsort(a, axis=1)          # positions, ascending
    top = order[:, ::-1][:, :2]            # positions of the two largest
    return np.take_along_axis(a, top, axis=1)
